/** Static vtable instance for the CycloneDDS backend. */
static const HsilDdsOps kCycloneDdsOps =
{
    cycloneInit,
    cycloneDestroy,
    cycloneCreateGroupedWriter,
    cycloneCreateStreamingWriter,
    cycloneDestroyWriter,
    cycloneWriteGrouped,
    cycloneWriteStreaming,
    cycloneCreateGroupedReader,
    cycloneCreateStreamingReader,
    cycloneDestroyReader,
    cycloneGetEndpointStatus
};

